import { Image } from 'react-native';

// Photos for the web harness and the no-camera fallback. Generated by
// scripts/gen-fixtures.mjs into e2e/fixtures/ (source of truth); Metro serves
// the copies in assets/fixtures/.
const sources = {
  cellar: require('../../assets/fixtures/cellar.png'),
  attic: require('../../assets/fixtures/attic.png'),
  bright: require('../../assets/fixtures/bright.png'),
  black: require('../../assets/fixtures/black.png'),
  outdoors: require('../../assets/fixtures/outdoors.png'),
} as const;

export type FixtureName = keyof typeof sources;
export const FIXTURE_NAMES = Object.keys(sources) as FixtureName[];
export const DEFAULT_FIXTURE: FixtureName = 'cellar';

export function isFixtureName(v: string | null | undefined): v is FixtureName {
  return !!v && (FIXTURE_NAMES as string[]).includes(v);
}

export function fixtureSource(name: FixtureName) {
  return sources[name];
}

// URI of a fixture, plus the pixel size the capture hash uses.
export function fixtureUri(name: FixtureName): string {
  return Image.resolveAssetSource(sources[name])?.uri ?? `fixture:${name}`;
}
